<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Testimonial; use Illuminate\Http\Request;
class TestimonialController extends Controller { public function index(){return view('admin.testimonials.index',['testimonials'=>Testimonial::orderBy('sort_order')->get()]);} public function create(){return view('admin.testimonials.form',['testimonial'=>new Testimonial]);} public function store(Request $r){Testimonial::create(array_merge($this->data($r),['is_active'=>$r->boolean('is_active')]));return redirect('/admin/testimonials')->with('ok','Testimoni ditambahkan.');} public function edit(Testimonial $testimonial){return view('admin.testimonials.form',compact('testimonial'));} public function update(Request $r,Testimonial $testimonial){$testimonial->update(array_merge($this->data($r),['is_active'=>$r->boolean('is_active')]));return redirect('/admin/testimonials')->with('ok','Testimoni diperbarui.');} public function destroy(Testimonial $testimonial){$testimonial->delete();return back()->with('ok','Testimoni dihapus.');} private function data($r){$d=$r->validate(['name'=>'required','role'=>'nullable','text'=>'required','rating'=>'required|integer|min:1|max:5','initial'=>'nullable|max:2','is_active'=>'nullable','sort_order'=>'nullable|integer']);$d['initial']=$d['initial']??strtoupper(substr($d['name'],0,1));return $d;} }
